 * Checks if the (date)time string is in a given format.
 *
 * @example
 * ```
 * Carbon::hasFormat('11:12:45', 'h:i:s'); // true
 * Carbon::hasFormat('13:12:45', 'h:i:s'); // false
 * ```
 *
 * @param string $date
 * @param string $format
 *
 * @return bool
 */
public static function hasFormat($date, $format)
{
    // createFromFormat() is known to handle edge cases silently.
    // E.g. "1975-5-1" (Y-n-j) will still be parsed correctly when "Y-m-d" is supplied as the format.
    // To ensure we're really testing against our desired format, perform an additional regex validation.

    return self::matchFormatPattern((string) $date, preg_quote((string) $format, '/'), static::$regexFormats);
}

/**
 * Checks if the (date)time string is in a given format.
 *
 * @example
 * ```
 * Carbon::hasFormatWithModifiers('31/08/2015', 'd#m#Y'); // true
 * Carbon::hasFormatWithModifiers('31/08/2015', 'm#d#Y'); // false
 * ```
 *
 * @param string $date
 * @param string $format
 *
 * @return bool
 */
public static function hasFormatWithModifiers($date, $format): bool
{
    return self::matchFormatPattern((string) $date, (string) $format, array_merge(static::$regexFormats, static::$regexFormatModifiers));
}

/**
 * Checks if the (date)time string is in a given format and valid to create a
 * new instance.
 *
 * @example
 * ```
 * Carbon::canBeCreatedFromFormat('11:12:45', 'h:i:s'); // true
 * Carbon::canBeCreatedFromFormat('13:12:45', 'h:i:s'); // false
 * ```
 *
 * @param string $date
 * @param string $format
 *
 * @return bool
 */
public static function canBeCreatedFromFormat($date, $format)
{
    try {
        // Try to create a DateTime object. Throws an InvalidArgumentException if the provided time string
        // doesn't match the format in any way.
        if (!static::rawCreateFromFormat($format, $date)) {
            return false;
        }
    } catch (InvalidArgumentException $e) {
        return false;
    }

    return static::hasFormatWithModifiers($date, $format);
}

/**
 * Returns true if the current date matches the given string.
 *
 * @example
 * ```
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('2019')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('2018')); // false
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('2019-06')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('06-02')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('2019-06-02')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('Sunday')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('June')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('12:23')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('12:23:45')); // true
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('12:23:00')); // false
 * var_dump(Carbon::parse('2019-06-02 12:23:45')->is('12h')); // true
 * var_dump(Carbon::parse('2019-06-02 15:23:45')->is('3pm')); // true
 * var_dump(Carbon::parse('2019-06-02 15:23:45')->is('3am')); // false
 * ```
 *
 * @param string $tester day name, month name, hour, date, etc. as string
 *
 * @return bool
 */
public function is(string $tester)
{
    $tester = trim($tester);

    if (preg_match('/^\d+$/', $tester)) {
        return $this->year === (int) $tester;
    }

    $sameMonthTester = preg_match('/^\d{3,}-\d{1,2}$/', $tester);
    $sameDayTester = preg_match('/^\d{1,2}-\d{1,2}$/', $tester);

    if ($sameMonthTester || $sameDayTester) {
        $timeToParse = $sameMonthTester ? $tester : $this->year.'-'.$tester;
        $parseFunction = static::$parseFunction;
        $parsed = null;

        if (!$parseFunction) {
            if ($timeToParse instanceof DateTimeInterface) {
                $parsed = static::instance($timeToParse);
            } else {
                try {
                    $constructorTime = $timeToParse;
                    $constructorTimezone = null;
                    $parsed = new static($constructorTime, $constructorTimezone);
                } catch (Exception $exception) {
                    $nowTimezone = null;
                    $now = static::now($nowTimezone);
                    if ($now instanceof DateTimeImmutable) {
                        $changeBase = $now;
                    } else {
                        $changeBase = clone $now;
                    }
                    $translatedModifier = strtr(trim($timeToParse), [
                        ' at ' => ' ',
                        'just now' => 'now',
                        'after tomorrow' => 'tomorrow +1 day',
                        'before yesterday' => 'yesterday -1 day',
                    ]);
                    $date = @$changeBase->change($translatedModifier);
                    if (!$date) {
                        throw new InvalidFormatException("Could not parse '$timeToParse': ".$exception->getMessage(), 0, $exception);
                    }
                    $parsed = $date;
                }
            }
        } else {
            if (\is_string($parseFunction) && method_exists(static::class, $parseFunction)) {
                $parseFunction = [static::class, $parseFunction];
            }
            $parsed = $parseFunction($timeToParse, null);
        }

        if (!$parsed) {
            $resolvedTimezone = $this->getTimezone();
            $resolved = static::now($resolvedTimezone);
        } elseif (\is_string($parsed)) {
            $resolved = static::parse($parsed, $this->getTimezone());
        } else {
            $expectedKinds = ['null', 'string'];
            $typeMessage = 'Expected ';
            foreach ($expectedKinds as $expectedKind) {
                $typeMessage .= "$expectedKind, ";
            }
            if (!$parsed instanceof DateTime && !$parsed instanceof DateTimeInterface) {
                $actualType = \is_object($parsed) ? \get_class($parsed) : \gettype($parsed);
                throw new InvalidTypeException($typeMessage.'DateTime or DateTimeInterface, '.$actualType.' given');
            }
            if ($parsed instanceof self) {
                $resolved = $parsed;
            } else {
                $resolved = new static($parsed->format('Y-m-d H:i:s.u'), $parsed->getTimezone());
                if ($parsed instanceof CarbonInterface) {
                    $importedSettings = [];
                    $settingsMap = [
                        'localStrictModeEnabled' => 'strictMode',
                        'localMonthsOverflow' => 'monthOverflow',
                        'localYearsOverflow' => 'yearOverflow',
                        'localHumanDiffOptions' => 'humanDiffOptions',
                        'localToStringFormat' => 'toStringFormat',
                        'localSerializer' => 'toJsonFormat',
                        'localMacros' => 'macros',
                        'localGenericMacros' => 'genericMacros',
                        'locale' => 'locale',
                        'tzName' => 'timezone',
                        'localFormatFunction' => 'formatFunction',
                    ];
                    foreach ($settingsMap as $property => $key) {
                        $value = $parsed->$property ?? null;
                        if ($value !== null) {
                            $importedSettings[$key] = $value;
                        }
                    }
                    if (!$parsed->hasLocalTranslator()) {
                        unset($importedSettings['locale']);
                    }
                    $resolved->settings($importedSettings);
                }
            }
        }

        if ($sameMonthTester) {
            $monthFormat = 'Y-m';
            $currentMonth = parent::format($monthFormat);
            $resolvedMonth = $resolved->rawFormat($monthFormat);

            return $currentMonth === $resolvedMonth;
        }

        $methodName = 'isSameDay';
        $unitToken = rtrim($methodName, 's');
        if (str_starts_with($unitToken, 'is')) {
            $word = substr($unitToken, 2);
            if (!\in_array($word, static::$days, true)
                && $word !== 'Utc'
                && $word !== 'UTC'
                && $word !== 'Local'
                && $word !== 'Valid'
                && $word !== 'DST'
            ) {
                $action = substr($unitToken, 0, 3);
                if ($action !== 'set') {
                    if (!\in_array($unitToken, static::$units, true)) {
                        if ($action !== 'add' && $action !== 'sub') {
                            $modifiableUnits = [];
                            $modifiableUnits[] = 'millennium';
                            $modifiableUnits[] = 'century';
                            $modifiableUnits[] = 'decade';
                            $modifiableUnits[] = 'quarter';
                            $modifiableUnits[] = 'week';
                            $modifiableUnits[] = 'weekday';
                            if (!\in_array($unitToken, $modifiableUnits, true) && !\in_array($unitToken, static::$units, true)) {
                                $six = substr($unitToken, 0, 6);
                                if ($six !== 'isLast' && $six !== 'isNext' && $six === 'isSame') {
                                    $unit = strtolower(substr($unitToken, 6));
                                    $unitFormats = [];
                                    $unitFormats['year'] = 'Y';
                                    $unitFormats['week'] = 'o-W';
                                    $unitFormats['day'] = 'Y-m-d';
                                    $unitFormats['hour'] = 'Y-m-d H';
                                    $unitFormats['minute'] = 'Y-m-d H:i';
                                    $unitFormats['second'] = 'Y-m-d H:i:s';
                                    $unitFormats['micro'] = 'Y-m-d H:i:s.u';
                                    $unitFormats['microsecond'] = 'Y-m-d H:i:s.u';
                                    $format = $unitFormats[$unit] ?? 'Y-m-d';
                                    $currentDay = parent::format($format);
                                    $resolvedDay = $resolved->rawFormat($format);

                                    return $currentDay === $resolvedDay;
                                }
                            }
                        }
                    }
                }
            }
        }

        $fallbackDayFormat = 'Y-m-d';
        $currentFallbackDay = parent::format($fallbackDayFormat);
        $resolvedFallbackDay = $resolved->rawFormat($fallbackDayFormat);

        return $currentFallbackDay === $resolvedFallbackDay;
    }

    $modifier = preg_replace('/(\d)h$/i', '$1:00', $tester);
    if ($modifier === null) {
        $modifier = $tester;
    }
    /* @var CarbonInterface $max */
    $median = static::parse('5555-06-15 12:30:30.555555')->modify($modifier);
    if ($this instanceof DateTimeImmutable) {
        $current = $this;
    } else {
        $current = clone $this;
    }
    /* @var CarbonInterface $other */
    if ($this instanceof DateTimeImmutable) {
        $other = $this;
    } else {
        $other = clone $this;
    }
    $other = $other->modify($modifier);

    if ($other === null) {
        @trigger_error("Since 2.61.0, it's deprecated to compare a date to null, meaning of such comparison is ambiguous and will no longer be possible in 3.0.0, you should explicitly pass 'now' or make an other check to eliminate null values.", \E_USER_DEPRECATED);
    }
    if (\is_bool($other)) {
        @trigger_error("Since 2.61.0, it's deprecated to compare a date to true or false, meaning of such comparison is ambiguous and will no longer be possible in 3.0.0, you should explicitly pass 'now' or make an other check to eliminate boolean values.", \E_USER_DEPRECATED);
    }
    if ($current == $other) {
        return true;
    }

    if (preg_match('/\d:\d{1,2}:\d{1,2}$/', $tester)) {
        $boundaryHour = (int) $current->hour;
        $boundaryMinute = (int) $current->minute;
        $boundarySecond = (int) $current->second;
        $boundaryMicro = 0;
        $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);

        return $current == $other;
    }

    if (preg_match('/\d:\d{1,2}$/', $tester)) {
        return $current->startOfMinute()->eq($other);
    }

        }

        if (preg_match('/\d(h|am|pm)$/', $tester)) {
            return $current->startOfHour()->eq($other);
        }

        if (preg_match(
            '/^(january|february|march|april|may|june|july|august|september|october|november|december)\s+\d+$/i',
            $tester
        )) {
            return $current->startOfMonth()->eq($other->startOfMonth());
        }

        $units = [
            'month' => [1, 'year'],
            'day' => [1, 'month'],
            'hour' => [0, 'day'],
            'minute' => [0, 'hour'],
            'second' => [0, 'minute'],
            'microsecond' => [0, 'second'],
        ];

        foreach ($units as $unit => [$minimum, $startUnit]) {
            if ($minimum === $median->$unit) {
                $normalizedUnit = rtrim(mb_strtolower($startUnit), 's');
                if ($normalizedUnit === 'centurie') {
                    $normalizedUnit = 'century';
                }
                if ($normalizedUnit === 'millennia') {
                    $normalizedUnit = 'millennium';
                }
                if ($normalizedUnit === 'year') {
                    $boundaryYear = (int) $current->year;
                    $boundaryMonth = 1;
                    $boundaryDay = 1;
                    $current = $current->setDate($boundaryYear, $boundaryMonth, $boundaryDay);
                    $boundaryHour = 0;
                    $boundaryMinute = 0;
                    $boundarySecond = 0;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                } elseif ($normalizedUnit === 'month') {
                    $boundaryYear = (int) $current->year;
                    $boundaryMonth = (int) $current->month;
                    $boundaryDay = 1;
                    $current = $current->setDate($boundaryYear, $boundaryMonth, $boundaryDay);
                    $boundaryHour = 0;
                    $boundaryMinute = 0;
                    $boundarySecond = 0;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                } elseif ($normalizedUnit === 'day') {
                    $boundaryHour = 0;
                    $boundaryMinute = 0;
                    $boundarySecond = 0;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                } elseif ($normalizedUnit === 'hour') {
                    $boundaryHour = (int) $current->hour;
                    $boundaryMinute = 0;
                    $boundarySecond = 0;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                } elseif ($normalizedUnit === 'minute') {
                    $boundaryHour = (int) $current->hour;
                    $boundaryMinute = (int) $current->minute;
                    $boundarySecond = 0;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                } elseif ($normalizedUnit === 'second') {
                    $boundaryHour = (int) $current->hour;
                    $boundaryMinute = (int) $current->minute;
                    $boundarySecond = (int) $current->second;
                    $boundaryMicro = 0;
                    $current = $current->setTime($boundaryHour, $boundaryMinute, $boundarySecond, $boundaryMicro);
                }

                break;
            }
        }

        return $current == $other;
    }

    /**
     * Checks if the (date)time string is in a given format with
     * given list of pattern replacements.
     *
     * @example
     * ```
     * Carbon::hasFormat('11:12:45', 'h:i:s'); // true
     * Carbon::hasFormat('13:12:45', 'h:i:s'); // false
     * ```
     *
     * @param string $date
     * @param string $format
     * @param array  $replacements
     *
     * @return bool
     */
    private static function matchFormatPattern(string $date, string $format, array $replacements): bool
    {
        // Preg quote, but remove escaped backslashes since we'll deal with escaped characters in the format string.
        $regex = str_replace('\\\\', '\\', $format);
        // Replace not-escaped letters
        $regex = preg_replace_callback(
            '/(?<!\\\\)((?:\\\\{2})*)(['.implode('', array_keys($replacements)).'])/',
            function ($match) use ($replacements) {
                return $match[1].strtr($match[2], $replacements);
            },
            $regex
        );
        // Replace escaped letters by the letter itself
        $regex = preg_replace('/(?<!\\\\)((?:\\\\{2})*)\\\\(\w)/', '$1$2', $regex);
        // Escape not escaped slashes
        $regex = preg_replace('#(?<!\\\\)((?:\\\\{2})*)/#', '$1\\/', $regex);

        return (bool) @preg_match('/^'.$regex.'$/', $date);
    }

    /**
     * Returns true if the date was created using CarbonImmutable::startOfTime()
     *
     * @return bool
     */
    public function isStartOfTime(): bool
    {
        return $this->startOfTime ?? false;
    }

    /**
     * Returns true if the date was created using CarbonImmutable::endOfTime()
     *
     * @return bool
     */
    public function isEndOfTime(): bool
    {
        return $this->endOfTime ?? false;
    }

    private function discourageNull($value): void
    {
        if ($value === null) {
            @trigger_error("Since 2.61.0, it's deprecated to compare a date to null, meaning of such comparison is ambiguous and will no longer be possible in 3.0.0, you should explicitly pass 'now' or make an other check to eliminate null values.", \E_USER_DEPRECATED);
        }
    }

    private function discourageBoolean($value): void
    {
        if (\is_bool($value)) {
            @trigger_error("Since 2.61.0, it's deprecated to compare a date to true or false, meaning of such comparison is ambiguous and will no longer be possible in 3.0.0, you should explicitly pass 'now' or make an other check to eliminate boolean values.", \E_USER_DEPRECATED);
        }
    }
}

